package com.anthony6996.hardcorecompass.listener;
import com.anthony6996.hardcorecompass.config.ConfigManager;import com.anthony6996.hardcorecompass.manager.CompassManager;import org.bukkit.Location;import org.bukkit.Material;import org.bukkit.block.Block;import org.bukkit.entity.Player;import org.bukkit.event.*;import org.bukkit.event.block.*;import org.bukkit.event.entity.EntityExplodeEvent;import org.bukkit.event.block.BlockExplodeEvent;import org.bukkit.event.player.PlayerInteractEvent;import org.bukkit.inventory.EquipmentSlot;import org.bukkit.inventory.ItemStack;import org.bukkit.inventory.meta.CompassMeta;import org.bukkit.inventory.meta.ItemMeta;
public final class LodestoneListener implements Listener{
 private final CompassManager compasses;private final ConfigManager config;public LodestoneListener(CompassManager c,ConfigManager cfg){compasses=c;config=cfg;}
 @EventHandler(priority=EventPriority.HIGHEST,ignoreCancelled=true) public void onPlace(BlockPlaceEvent e){ItemStack placed=e.getItemInHand();if(!compasses.isHardcoreLodestone(placed))return;Location at=e.getBlockPlaced().getLocation();if(compasses.tooClose(at)){e.setCancelled(true);e.getPlayer().sendMessage(config.getMessage(e.getPlayer(),"lodestone-too-close").replace("{distance}",Integer.toString(config.lodestoneMinSeparation())));return;}ItemMeta meta=placed.getItemMeta();String label=meta!=null&&meta.hasDisplayName()?meta.getDisplayName():null;compasses.markPlacedLodestone(e.getBlockPlaced(),e.getPlayer().getUniqueId(),label);}
 @EventHandler(priority=EventPriority.HIGHEST,ignoreCancelled=false) public void onInteract(PlayerInteractEvent e){if(e.getHand()!=EquipmentSlot.HAND||e.getClickedBlock()==null||!e.getAction().isRightClick()||e.getClickedBlock().getType()!=Material.LODESTONE)return;Player p=e.getPlayer();ItemStack hand=p.getInventory().getItemInMainHand();if(!compasses.isHardcoreCompass(hand))return;e.setCancelled(true);Block block=e.getClickedBlock();if(!compasses.isHardcoreLodestoneBlock(block)){p.sendMessage(config.getMessage(p,"hardcore-lodestone-only"));return;}Location next=block.getLocation();boolean rebound=false;if(hand.getItemMeta() instanceof CompassMeta meta&&meta.hasLodestone()){Location old=meta.getLodestone();rebound=old!=null&&old.getWorld()!=null&&(!old.getWorld().equals(next.getWorld())||old.getBlockX()!=next.getBlockX()||old.getBlockY()!=next.getBlockY()||old.getBlockZ()!=next.getBlockZ());}compasses.bind(hand,p,next);p.getInventory().setItemInMainHand(hand);p.updateInventory();p.sendMessage(config.getMessage(p,rebound?"compass-rebound":"compass-bound"));}
 @EventHandler(priority=EventPriority.HIGHEST,ignoreCancelled=true) public void onBreak(BlockBreakEvent e){Block b=e.getBlock();if(!compasses.isHardcoreLodestoneBlock(b))return;Player p=e.getPlayer();if(!compasses.mayBreak(b,p)){e.setCancelled(true);p.sendMessage(config.getMessage(p,"lodestone-break-denied"));return;}destroy(b,p);e.setDropItems(false);}
 private void destroy(Block b,Player breaker){String label=compasses.lodestoneLabel(b);if(!compasses.removeLodestone(b))return;compasses.markTargetLost(b.getWorld(),b.getLocation());b.getWorld().dropItemNaturally(b.getLocation(),compasses.createLodestone(breaker,label));}
 @EventHandler(priority=EventPriority.HIGHEST,ignoreCancelled=true) public void onEntityExplode(EntityExplodeEvent e){e.blockList().removeIf(b->{if(!compasses.isHardcoreLodestoneBlock(b))return false;destroy(b,null);return true;});}
 @EventHandler(priority=EventPriority.HIGHEST,ignoreCancelled=true) public void onBlockExplode(BlockExplodeEvent e){e.blockList().removeIf(b->{if(!compasses.isHardcoreLodestoneBlock(b))return false;destroy(b,null);return true;});}
}
